  "hBP01-114": [
    {
      "path": "abilityText",
      "original": "■這個工具裝備的Holomen，其Arts+20。\n■當這個工具裝備的Holomen使用Arts時，對該Holomen造成10點特殊傷害。\n\n◆若裝備在1st以上的〈アキ・ローゼンタール〉上，則追加以下能力：\n[每回合1次] 當這個Holomen因自己的能力而回復時，抽1張自己的卡牌。\n\n工具每位Holomen身上只能裝備1張。",
      "translation": "■此道具所附加的成員，其藝能+20。\n■此道具所附加的成員使用藝能時，對此成員造成10點特殊傷害。\n\n◆附加到1st或以上的〈アキ・ローゼンタール〉時追加以下能力\n[每回合1次]此成員因己方的能力回復HP時，從自己的牌庫抽1張卡。\n\n自己的每位成員只能附加1張道具。",
      "sourceUrl": "https://hololive-official-cardgame.com/cardlist/?id=1278&%2Fcardlist%2Fcardsearch_ex=&view=text",
      "reason": "自分の能力指己方能力，不限此成員自己的能力。",
      "method": "sentence_semantics"
    }
  ],
  "hBP01-115": [
    {
      "path": "abilityText",
      "original": "這個工具裝備的Holomen，Arts+10。\n\n◆若裝備在1st以上的〈星街すいせい〉，則追加能力：\n當這個工具所裝備的Holomen讓對手的Holomen倒下時，從自己應援牌庫頂抽1張牌，送給該Holomen。\n\n工具每位Holomen只能裝備1張。",
      "translation": "此道具所附加的成員，其藝能+10。\n\n◆附加到1st或以上的〈星街すいせい〉時追加以下能力\n此道具所附加的成員擊倒對手成員時，將自己聲援牌庫頂的1張卡附加到此成員。\n\n自己的每位成員只能附加1張道具。",
      "sourceUrl": "https://hololive-official-cardgame.com/cardlist/?id=156&%2Fcardlist%2Fcardsearch_ex=&view=text",
      "reason": "附加聲援不經手牌。",
      "method": "sentence_semantics"
    }
  ],
  "hBP01-122": [
    {
      "path": "abilityText",
      "original": "在對手的回合中，若裝備了此應援的Holomen被擊倒時，從自己應援牌庫頂抽1張，送到自己的〈アキ・ローゼンタール〉上。\n\n此應援只能裝備在自己的〈アキ・ローゼンタール〉上，同一角色可以裝備任意張數。",
      "translation": "在對手的回合，此粉絲所附加的成員被擊倒時，將自己聲援牌庫頂的1張卡附加到自己的1位〈アキ・ローゼンタール〉。\n\n此粉絲只能附加到自己的〈アキ・ローゼンタール〉，每位可附加任意張數。",
      "sourceUrl": "https://hololive-official-cardgame.com/cardlist/?id=163&%2Fcardlist%2Fcardsearch_ex=&view=text",
      "reason": "粉絲卡不是聲援卡；聲援附加不經手牌。",
      "method": "sentence_semantics"
    }
  ],
  "hBP01-124": [
    {
      "path": "abilityText",
      "original": "在對手的回合中，若裝備此應援的Holomen被擊倒，將該Holomen上的1張應援，轉移到自己其他的Holomen上。\n\n此應援只能裝備在自己的〈AZKi〉上，且同一角色可裝備任意張數。",
      "translation": "在對手的回合，此粉絲所附加的成員被擊倒時，將該成員的1張聲援卡改附加到自己的其他1位成員。\n\n此粉絲只能附加到自己的〈AZKi〉，每位可附加任意張數。",
      "sourceUrl": "https://hololive-official-cardgame.com/cardlist/?id=165&%2Fcardlist%2Fcardsearch_ex=&view=text",
      "reason": "粉絲卡與聲援卡是不同卡類。",
      "method": "sentence_semantics"
    }
  ],
