      "translation": "必須在不包含這張卡的情況下，自己的手牌必須為6張以下才能使用此卡。\n\n查看自己牌庫頂的4張牌，從中可公開任意數量持有#お酒的Holomen，將公開的Holomen加入手牌。然後將剩下的卡以任意順序放回牌庫底。\n\nLIMITED：每回合只能使用1張。",
