      "original": "這位粉絲所附屬的 holomen，其術式 +10。\n\n這位粉絲只能附加在自己的〈Ouro Kronii〉身上，每位最多可附加任意張。",
      "translation": "這位粉絲所附屬的 holomen，其藝能 +10。\n\n這位粉絲只能附加在自己的〈Ouro Kronii〉身上，每位最多可附加任意張。",
