      "original": "[每回合1次]當自己的任一位Holomen要從對手那裡承受Arts傷害時，可以選擇自己舞台上[Buzz或2nd]位置的一位紅色Holomen：該次傷害改由所選的Holomen承受。",
      "translation": "[每回合1次]自己的1位成員將要受到對手的藝能傷害時，可以選擇自己舞台上的1位[Buzz或2nd]紅色成員：該次傷害改由所選成員承受。",
