      "original": "每有1張這位Holomen的應援，此Arts的攻擊力+20。以此Arts令對手的Holomen倒下時，從自己的應援牌庫頂抽1張，送到這位Holomen身上。",
      "translation": "此成員每附加1張聲援卡，此藝能便+20。此藝能擊倒對手成員時，將自己聲援牌庫頂的1張卡附加到此成員。",
