      "original": "在對手的回合中，當自己的後排夥伴受到對手的特殊傷害時，可以將重疊在這名夥伴上的1張夥伴放進檔案區：在這回合內，自己的所有後排夥伴不會受到特殊傷害。",
      "translation": "在對手的回合，自己的後備成員將要受到對手的特殊傷害時，可以將此卡下方重疊的1張成員卡送入存檔區：本回合中，自己的所有後備成員不會受到特殊傷害。",
      "sourceUrl": "https://hololive-official-cardgame.com/cardlist/?id=1780&%2Fcardlist%2Fcardsearch_ex=&view=text",
      "reason": "本卡支付重疊卡費用；發動時機在受到特殊傷害前。",
