      "original": "[每回合1次]在自己的主要步驟中，可以將自己〈ジジ・ムリン〉下方重疊的1張Holomen放入檔案區域：從自己的應援牌庫頂抽1張卡，直接疊放到這位Holomen之下。",
      "translation": "[每回合1次]在自己的主要階段，可以將自己的〈ジジ・ムリン〉下方重疊的1張成員卡送入存檔區：將自己聲援牌庫頂的1張卡附加到此成員。",
